<template><section class="admin-page"><AdminHero title="角色管理" :icon="Key"><template #extra><el-button type="primary" :icon="Plus" @click="createRole">新增角色</el-button></template></AdminHero><AdminPanel><RoleFilters v-model:keyword="keyword" v-model:status="status" @search="search" @reset="reset"/><ResponsiveList><template #desktop><RoleTableList :items="pagedItems" :loading="loading" @edit="editRole" @delete="deleteRole"/></template><template #mobile><RoleCardList :items="pagedItems" @edit="editRole" @delete="deleteRole"/></template></ResponsiveList><el-empty v-if="!loading&&!filteredItems.length" description="暂无角色"/><TablePager v-model="page" v-model:page-size="limit" :total="filteredItems.length"/></AdminPanel></section></template>
<script setup lang="ts">import{computed,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{Key,Plus}from'@element-plus/icons-vue';import{useRouter}from'vue-router';import AdminHero from '@/components/admin/AdminHero.vue';import AdminPanel from '@/components/admin/AdminPanel.vue';import ResponsiveList from '@/components/common/ResponsiveList.vue';import TablePager from '@/components/common/TablePager.vue';import RoleFilters from './components/RoleFilters.vue';import RoleTableList from './components/RoleTableList.vue';import RoleCardList from './components/RoleCardList.vue';import{listRoles,removeRole}from'./rolePrototypeStore';import type{RoleItem}from'./types';const router=useRouter();const source=listRoles();const loading=ref(false);const keyword=ref('');const status=ref<0|1|undefined>();const page=ref(1);const limit=ref(15);const appliedKeyword=ref('');const appliedStatus=ref<0|1|undefined>();const filteredItems=computed(()=>source.filter(item=>(appliedStatus.value===undefined||item.status===appliedStatus.value)&&(!appliedKeyword.value||item.name.toLowerCase().includes(appliedKeyword.value.toLowerCase()))));const pagedItems=computed(()=>filteredItems.value.slice((page.value-1)*limit.value,page.value*limit.value));function search(){appliedKeyword.value=keyword.value.trim();appliedStatus.value=status.value;page.value=1}function reset(){keyword.value='';status.value=undefined;search()}function createRole(){void router.push({name:'RoleCreate'})}function editRole(row:RoleItem){void router.push({name:'RoleEdit',params:{id:row.id}})}async function deleteRole(row:RoleItem){if(row.admin_count>0)return;await ElMessageBox.confirm(`确定删除角色“${row.name}”吗？`,'删除角色',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});removeRole(row.id);ElMessage.success('角色已删除')}</script>
